catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading || newValue == '') {
      return;
   }

    var ga = new GlideAjax('OWS_Availability');
    ga.addParam('sysparm_name', 'getAnswer');
	ga.addParam('sysparm_evStart', g_form.getValue('event_start_date'));
	ga.addParam('sysparm_evEnd', g_form.getValue('event_end_date'))
	ga.addParam('sysparm_evSpace', g_form.getValue('requested_room'));
    ga.getXML(spaceAvailable);

    function spaceAvailable(response) {

        var answer = response.responseXML.documentElement.getAttribute("answer");
        if (answer != null){
        alert(answer + '. Please select a different room.');
		g_form.setValue('requested_room','');
		}
        else{
			//alert("Rocky - OWS ");
		}
    }

}
